package in.artisanconnect.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="order_status_history") public class OrderEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public PurchaseOrder order; @Enumerated(EnumType.STRING) public PurchaseOrder.Status status; @Column(length=500) public String note; @Column(nullable=false,updatable=false) public Instant createdAt=Instant.now(); public OrderEvent(){} public OrderEvent(PurchaseOrder o,PurchaseOrder.Status s,String n){order=o;status=s;note=n;} public Long getId(){return id;} public PurchaseOrder getOrder(){return order;} public PurchaseOrder.Status getStatus(){return status;} public String getNote(){return note;} public Instant getCreatedAt(){return createdAt;} }
